/**
 * emit to subscription queries of type FindLoanAccount,
 * but only if the id matches
 *
 * @param		entity	LoanAccount
 */
	protected void emitFindLoanAccount( LoanAccount entity ) {
		LOGGER.info("handling emitFindLoanAccount" );
		
	    queryUpdateEmitter.emit(FindLoanAccountQuery.class,
	                            query -> query.getFilter().getLoanAccountId().equals(entity.getLoanAccountId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllLoanAccount
	 * 
	 * @param		entity	LoanAccount
	 */
	protected void emitFindAllLoanAccount( LoanAccount entity ) {
		LOGGER.info("handling emitFindAllLoanAccount" );
		
	    queryUpdateEmitter.emit(FindAllLoanAccountQuery.class,
	                            query -> true,
	                            entity);
	}

